import itertools

def find_counterexample(m):
    import random
    # Try random multisets
    for _ in range(100000):
        n = [random.randint(0, m - 1) for _ in range(m)]
        if sum(n) % m == 0:
            continue

        # Check all permutations (since m is small)
        found = False
        for p in itertools.permutations(n):
            if sum((i + 1) * p[i] for i in range(m)) % m == 0:
                found = True
                break
        if not found:
            return n
    return None

for m in range(2, 11):
    ce = find_counterexample(m)
    print(f"m={m}: {ce}")

import random

def check_permutation_exists(m, n, trials=10000):
    # Try to find a permutation sigma such that sum(i * n[sigma(i)]) % m == 0
    # We use random shuffling
    temp_n = list(n)
    for _ in range(trials):
        random.shuffle(temp_n)
        if sum((i + 1) * temp_n[i] for i in range(m)) % m == 0:
            return True
    return False

def is_m_likely_true(m, trials=1000):
    # For a given m, test many random multisets
    for _ in range(trials):
        n = [random.randint(0, m - 1) for _ in range(m)]
        if sum(n) % m == 0:
            continue
        if not check_permutation_exists(m, n):
            return False # Found a multiset that likely has no permutation
    return True

