import itertools

def check_all_permutations(m, n):
    # To speed up, use the multiset property
    from collections import Counter
    counts = Counter(n)
    distinct_vals = list(counts.keys())
    val_counts = list(counts.values())

    memo = {}
    def solve(slot, s, rem_counts):
        state = (slot, s, rem_counts)
        if state in memo: return memo[state]
        if slot == m + 1:
            return s % m == 0

        for i in range(len(distinct_vals)):
            if rem_counts[i] > 0:
                new_counts = list(rem_counts)
                new_counts[i] -= 1
                if solve(slot + 1, (s + slot * distinct_vals[i]) % m, tuple(new_counts)):
                    memo[state] = True
                    return True
        memo[state] = False
        return False

    return solve(1, 0, tuple(val_counts))

